{
	OBJECT_BASIC_METHODS(CRPGItem);
public:
	int nWeight; // in grams
	int nSubTypePriority;
	EItemSubType subType;
	CTPoint<int> sSize;
	CPtr<CString> pToolTip;
	CPtr<CString> pName;
	CPtr<CString> pDescription;
