void CRPGItem::Import()
{
	NDatabase::ImportField( "Weight", &nWeight );
	NDatabase::ImportField( "SizeX",	&sSize.x );
	NDatabase::ImportField( "SizeY",	&sSize.y );
	NDatabase::ImportField( "TooltipID", &pToolTip );
	NDatabase::ImportField( "ModelID", &pModel );
	NDatabase::ImportField( "ModelActive1", &pModelActive );
	NDatabase::ImportField( "Model1", &pModelInactive );

void CShowItemModel::Set( NGScene::IGameView *pView, NWorld::CUnit *_pUnit, NRPG::IInventoryItem *_pItem, NDb::ECameraType eCameraType )
{
	pItem = _pItem;
	pUnit = _pUnit;

	// retail @0x1c0f50 calls GetItemInfo unconditionally -- no null-item guard exists there.
	CPtr<NDb::CRPGItem> pRPGItem( pItem->GetDBItem() );

	SRand sRnd;
	if ( pRPGItem->pModel )
	{
		const NDb::SCameraParams &sCamera = pRPGItem->sCameras[eCameraType];

		CVec3 vForwardDir;
		CQuat q = CQuat( sCamera.fYaw, V3_AXIS_Z ) * CQuat( sCamera.fPitch, V3_AXIS_X );
		q.GetYAxis( &vForwardDir );

		CVec3 vCP( sCamera.vAnchor - vForwardDir * sCamera.fDistance );
		SHMatrix sCameraTransform;
		MakeMatrix( &sCameraTransform, sCamera.fPitch, sCamera.fYaw, sCamera.fRoll, vCP );

		SetScene( pView, true );
		SetModel( pRPGItem->pModel->CreateModel( &sRnd ) );
		SetCameraTransform( sCameraTransform );

CDynamicCast<NRPG::IToolItem> pTool( pItem );
CDynamicCast<NRPG::IPicklockItem> pPicklock( pItem );
CDynamicCast<NRPG::IMineItem> pMine( pItem );
CDynamicCast<NRPG::IKeyItem> pKey( pItem );
CDynamicCast<NRPG::IClueItem> pClue( pItem );

// retail public overload @0x34b340: (pMap, pos, rot, pInvItem, bool bTemporaryVisible, int nFloor);
// @0x74b45d forwards bTemporaryVisible as the inner overload's arg 6 and hardwires bVisibleGated 0.
CDFrozenItem* CDebrisController::AddFrozenItem( NAI::IAIMap *pMap, const CVec3 &pos, const CQuat &rot, NRPG::IInventoryItem *pInvItem, bool bTemporaryVisible, int nFloor )
{
	CPtr<NRPG::IInventoryItem> pHold( pInvItem );
	if ( !IsValid( pInvItem->GetDBItem()->pModel ) )
	{
		ASSERT( 0 );
		return 0;
	}
	SRand rnd;
	SHMatrix m;
	MakeMatrix( &m, pos, rot );
	CDFrozenItem *pWorldItem = AddFrozenItem( pMap, m, pInvItem, pInvItem->GetDBItem()->pModel->CreateModel( &rnd ), nFloor, bTemporaryVisible );
	return pWorldItem;
